HALL = ['key:Escape', 'user:manager', 'click:menutop:Revenue & Sales', 'click:menuleaf:Hall booking', 'click:tab:Enquiries']
OWNER_HALL = ['key:Escape', 'user:owner', 'click:menutop:Revenue & Sales', 'click:menuleaf:Hall booking']
chapter(15, 'Hall booking', 'Take an enquiry for the Kulkarni engagement, write the quotation with terms, let the Owner record the terms override, accept it with an advance and read the event dialog with the event-day bill.',
        'Meera (Manager)', 'manager', menu='Revenue & Sales > Hall booking')
step('Meera is on Modules Home. The halls are sold from the Revenue & Sales module: Sagar Hall, Moti Hall and the Garden Lawn.', 'A hall booking is an event with its own enquiry, quotation, advances and bill.', target='sel:.fit-home-grid', auto=['key:Escape', 'user:manager'], action='read', expect='Modules Home for Meera.', check="ctx.uid==='manager'")
tile('Revenue & Sales', 'Click the Revenue & Sales tile.', 'Hall booking is one of its tiles.', expect='The Revenue & Sales page opens.')
leaf('Revenue & Sales', 'Hall booking', 'Click the Hall booking tile.', 'The page follows the sales path from enquiry to event.', expect='The Hall booking page opens.', check="ctx.page==='hall-booking'")
read('The tabs are Enquiries, Quotations, Calendar, Events, Menus and Templates. The top figures show follow-ups due today, open enquiries, quotations out and events ahead. Advances carry no GST; GST is charged on the tax invoice.', 'The tabs are the steps of a sale in order.', target='tab:Enquiries', expect='The hall page and its six tabs.')
click('btn:New enquiry', 'Click New enquiry. Mr. Suresh Kulkarni wants a hall for an engagement on 7 November.', 'Every call is logged as an enquiry with a follow-up date, so none is forgotten.', expect='The New hall enquiry dialog opens.', check="has('Add enquiry')")
step('Type the customer Mr. Suresh Kulkarni and the phone 9800000005. Choose the event Engagement.', 'The type of event decides the terms and the price lists.', target='field:Customer name', auto=['type:field:Customer name|Mr. Suresh Kulkarni', 'type:field:Phone|9800000005', 'select:field:Event|Engagement'], action='type', expect='The customer and the event are filled.')
step('Set the event date 7 Nov, 120 expected guests, the hall Moti Hall and the part of the day Evening.', 'The hall and the part of the day are checked against the calendar.', target='field:Hall', auto=['type:field:Event date|2026-11-07', 'type:field:Expected guests|120', 'select:field:Hall|Moti Hall', 'select:field:Part of the day|Evening'], action='select', expect='The event details are filled.')
click('modalbtn:Add enquiry', 'Click Add enquiry.', 'The enquiry is listed under Open until it is quoted.', expect='The enquiry is added.', msgText='Enquiry added')
click('btn:Mr. Suresh Kulkarni', 'Click the enquiry to open it.', 'The enquiry card holds the details, the Hold the hall option and Mark lost.', expect='The enquiry ENQ-0001 opens.', check="has('Create quotation')")
click('modalbtn:Create quotation', 'Click Create quotation.', 'A quotation turns the enquiry into prices, a payment plan and terms.', expect='The New quotation form opens with the hall line Moti Hall, Evening, Rs 8,000.', check="has('Add menu')", allowError=True)
step('Choose the menu package Silver Veg, Rs 650 a plate, and click Add menu.', 'The menu is charged per plate for the guaranteed number of plates, 120.', target='btn:Add menu', auto=['select:field:Menu per plate|Silver', 'click:modalbtn:Add menu'], action='select', expect='Silver Veg for 120 plates is added to the lines.', allowError=True)
read('The quotation shows the lines with 18 per cent GST: hall hire, and the menu for 120 plates. The grand total is Rs 1,01,480. The payment plan is an advance of 25 per cent on acceptance, 50 per cent on 26 Oct and the balance on the event day. Discount is limited to 10 per cent for the manager.',
     'Advances carry no GST; the balance row takes any rounding difference.', target='dialog:', expect='The totals and the payment plan.')
read('The terms and conditions of the hotel are listed below the plan. In this demo every clause still says OWNER TO REPLACE, so Send is greyed out for the manager. The Owner replaces the text or records an override with a reason.',
     'A quotation with unfinished terms must not go to a customer.', target='btn:Send', expect='The terms with the OWNER TO REPLACE warning.')
click('modalbtn:Save draft', 'Click Save draft.', 'The draft waits for the Owner.', expect='The quotation is saved as a draft.', allowError=True)
step('Sagar, the Owner, opens the Quotations tab, opens QT/2627/0001 and clicks Override (Owner).', 'Only the Owner may send a quotation with unfinished terms, and must say why.', target='field:Reason for sending',
     auto=['key:Escape', 'user:owner', 'click:menutop:Revenue & Sales', 'click:menuleaf:Hall booking', 'click:tab:Quotations', 'click:btn:QT/2627/0001', 'click:modalbtn:Override (Owner)'], action='click', expect='A reason box and a Record override button appear.', check="has('Record override')", allowError=True)
typ('field:Reason for sending', 'Terms to be replaced after the CA review', 'Type the reason: Terms to be replaced after the CA review.', 'The override and its reason stay on the quotation for ever.', expect='Reason filled.')
click('modalbtn:Record override', 'Click Record override.', 'Send is now available.', expect='The override is recorded.')
click('modalbtn:Send', 'Click Send.', 'The quotation gets its number and a copy of the terms; later changes to the terms never alter it.', expect='QT/2627/0001 is sent to the customer.', msgText='Quotation QT/2627/0001 sent', check="has('Accept')")
click('modalbtn:Accept', 'The customer agrees. Click Accept.', 'Accepting turns the quotation into an event and blocks the hall on the calendar.', expect='The Accept quotation panel opens.', check="has('Accept and create event')")
step('Type the first advance received, 20000 rupees, paid by cash, and the manager reason for the number of guests: Round-table plan extended with a stage-side row.', 'The set-up seats 60 at round tables, so 120 guests need a manager\'s reason.', target='field:First advance received',
     auto=['type:field:First advance received|20000', 'type:field:Manager reason (above capacity)|Round-table plan extended with a stage-side row'], action='type', expect='The advance and the reason are filled.')
click('modalbtn:Accept and create event', 'Click Accept and create event.', 'The event HEV-0002 appears on the Events tab and the advance is a receipt without GST.', expect='The event is created.', msgText='Quotation accepted: the event is on the Events tab')
step('Open the Events tab and click the event HEV-0002.', 'The event dialog is the working file of the event until the day.', target='dialog:', auto=['key:Escape', 'click:tab:Events', 'click:btn:HEV-0002'], action='click', expect='The event dialog opens.', check="has('Function sheet')")
read('The dialog holds the function sheet, the advances and balance, the rooms for the guests, the event-day bill and the cancel option. Take advance records a further instalment, Block rooms holds rooms for the guests, Add extra item adds a charge such as extra plates.',
     'Everything about the event is on one dialog, so nothing lives on a paper sheet.', target='dialog:', expect='The event dialog.')
read('On the day, the actual plates are entered; the bill is for the plates served, not the guaranteed plates, at 18 per cent GST. The balance is settled by Pay now, Leave due or Company, and Close and bill finishes the event.', 'The event-day bill closes the sale and shows on the day close.', target='btn:Close and bill', expect='The event-day bill section.')
step('Close the dialog and open the Calendar tab.', 'The hall calendar shows which hall is taken on which day, so two events never collide.', target='tab:Calendar', auto=['key:Escape', 'click:tab:Calendar'], action='click', expect='The hall calendar opens.')
click('tab:Menus', 'Open the Menus tab.', 'The menu packages and their prices per plate are kept here.', expect='The menus are listed.')
